// Monetary amounts use integer cents, as in the imported reports.
let signalMinimum=300000;
function documentParts(value){
 const text=String(value||'').trim().replace(/\s+/g,' ');
 // Preserve document type and series. Only a separate final numeric token is a parcel.
 const match=text.match(/^((?:[A-Za-z]+ )?\d+(?: \d+)?) (\d{1,3})$/);
 return match?{base:match[1],parcel:match[2]}:{base:text,parcel:''};
}
function invoiceGroups(rows){
 const groups=new Map();
 for(const r of rows){
  const doc=documentParts(r.document),supplier=String(r.supplier_code||'').trim();
  const identity=supplier&&!/^0+$/.test(supplier)?supplier:normalize(r.supplier||'');
  // Unidentified suppliers/documents cannot safely identify a shared invoice.
  const key=JSON.stringify([r.regime,r.account,identity,doc.base,(!identity||!doc.base)?r.id:'']);
  if(!groups.has(key))groups.set(key,{key,base:doc.base,rows:[],total:0});
  const group=groups.get(key);group.rows.push(r);group.total+=r.actual;
 }
 return [...groups.values()];
}
function variationSignals(rs,old,year,available,priorAvailable){
 const header='<h2>O que explica a variação?</h2>';
 if(!available||!priorAvailable)return `<section class="panel">${header}<p>Comparação indisponível: importe as bases dos dois anos para este regime.</p></section>`;
 const now=new Map(grouped(rs,'account')),before=new Map(grouped(old,'account'));
 const labels=new Map([...old,...rs].map(r=>[r.account,r.vbz]));
 const changes=[...new Set([...now.keys(),...before.keys()])].map(code=>({code,now:now.get(code)||0,before:before.get(code)||0,delta:(now.get(code)||0)-(before.get(code)||0)})).sort((a,b)=>b.delta-a.delta);
 const increases=changes.filter(c=>c.delta>0),reductions=changes.filter(c=>c.delta<0),net=sum(rs)-sum(old);
 const top=increases.slice(0,2),topDelta=top.reduce((s,c)=>s+c.delta,0);
 const summary=net>0&&top.length?`${top.map(c=>esc(labels.get(c.code)||c.code)).join(' e ')} representam ${(topDelta/net*100).toFixed(1).replace('.',',')}% do aumento líquido de ${brl(net)}.`:net<0?`O total caiu ${brl(-net)}. As altas abaixo foram compensadas por reduções em outras contas.`:'O total não variou. Veja as altas e reduções que se compensaram.';
 // Drop only the month/year restriction when locating the other parcels.
 const context=db.entries.filter(r=>db.documentEntryIds.has(r.id)&&r.regime===$('regime').value&&!r.issue&&(!$('department').value||r.department===$('department').value)&&(!$('package').value||r.package===$('package').value)&&matchesAccount(r));
 const groups=invoiceGroups(context),currentIds=new Set(rs.map(r=>r.id)),priorIds=new Set(old.map(r=>r.id));
 const invoicesFor=(code,ids)=>groups.filter(g=>g.rows[0].account===code&&g.total>=signalMinimum&&g.rows.some(r=>ids.has(r.id)&&r.actual!==0)).map(g=>({g,period:sum(g.rows.filter(r=>ids.has(r.id)))})).sort((a,b)=>b.period-a.period).map(({g,period})=>{
  const movements=g.rows.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id);
  return `<details class="invoice"><summary><b>Documento / NF ${esc(g.base||'não informado')}</b> · ${esc(g.rows[0].supplier||'Fornecedor não informado')}<span>${brl(period)} no período · ${brl(g.total)} total identificado</span></summary>${table(['Documento / parcela','Data','Mês / ano','Realizado','No período'],movements.map(r=>`<tr><td>${esc(r.document)}<div class="detail">${esc(r.history)} · Importação #${r.import_id}, linha ${r.line}</div></td><td>${esc(dateBR(r.date))}</td><td>${months[Number(r.date.slice(5,7))-1]}/${esc(r.date.slice(0,4))}</td><td class="num">${brl(r.actual)}</td><td>${ids.has(r.id)?'Sim':'Outro período'}</td></tr>`))}</details>`;
 }).join('')||'<p class="detail">Nenhum documento com total identificado acima do limite e movimento neste período.</p>';
 return `<section class="panel signals">${header}<label class="signal-limit">Destacar documentos a partir de (R$)<input id="signalMinimum" type="number" min="0" step="0.01" value="${signalMinimum/100}"></label>${increases.map(c=>`<details class="signal-account"><summary><b>${esc(c.code)} · ${esc(labels.get(c.code))}</b><span class="bad">+${brl(c.delta)} ${c.before>0?'(+'+(c.delta/c.before*100).toFixed(1).replace('.',',')+'%)':c.before===0?'(sem despesa líquida anterior)':'(base anterior negativa)'}</span></summary><p>${year-1}: ${brl(c.before)} → ${year}: ${brl(c.now)}. ${net>0?(c.delta/net*100).toFixed(1).replace('.',',')+'% do aumento líquido.':''}</p><h3>Documentos do período · ${year}</h3>${invoicesFor(c.code,currentIds)}<h3>Documentos de comparação · ${year-1}</h3>${invoicesFor(c.code,priorIds)}</details>`).join('')||'<p>Nenhuma conta apresentou aumento neste período.</p>'}<p class="detail">Altas: ${brl(increases.reduce((s,c)=>s+c.delta,0))} · Reduções: ${brl(-reductions.reduce((s,c)=>s+c.delta,0))} · Diferença líquida: ${brl(net)}. Documentos são pistas para conferência; seu valor total não é o aumento da conta.</p>${reductions.length?'<details><summary>Ver contas que reduziram despesas</summary>'+table(['Conta',String(year-1),String(year),'Redução'],reductions.sort((a,b)=>a.delta-b.delta).map(c=>`<tr><td>${esc(c.code)} · ${esc(labels.get(c.code))}</td><td>${brl(c.before)}</td><td>${brl(c.now)}</td><td class="num">${brl(c.delta)}</td></tr>`))+'</details>':''}</section>`;
}

