let budgetStore=null,budgetLoading=false,budgetError='',budgetDirty=false,budgetSaving=false;
let budgetId='',budgetPage=0,budgetDepartment='',budgetPackage='',budgetQuery='',budgetMonth='';
let budgetLayout='monthly';
const budgetOffline=()=>location.protocol==='file:';
const budgetClone=value=>JSON.parse(JSON.stringify(value));
const budgetKey=r=>JSON.stringify([normalize(r.department),normalize(r.package),normalize(r.vbz).replace('conservacao de edificio e instalaco','conservacao de edificio e instalacoes').replace('instalacoeses','instalacoes')]);
const budgetTotal=values=>values.reduce((s,v)=>s+(v??0),0);
function budgetDelta(actual,target,available=true){
 if(!available||target===null)return {amount:null,percent:null};
 return {amount:actual-target,percent:target===0?null:(actual-target)/Math.abs(target)*100};
}
function budgetPercent(value){return value===null?'—':(value>0?'+':'')+value.toFixed(1).replace('.',',')+'%';}
function budgetDeltaCells(actual,target,available=true){const d=budgetDelta(actual,target,available);return `<td class="num ${d.amount>0?'bad':d.amount<0?'good':''}">${d.amount===null?'—':brl(d.amount)}</td><td class="num ${d.amount>0?'bad':d.amount<0?'good':''}">${budgetPercent(d.percent)}</td>`;}
const budgetUid=()=>globalThis.crypto?.randomUUID?.()||'p-'+Date.now()+'-'+Math.random().toString(36).slice(2);
function budgetValidate(data){
 if(data?.version!==1||!Array.isArray(data.plans)||data.plans.length>100)throw Error('Backup de planejamento inválido.');
 const ids=new Set();
 for(const p of data.plans){
  if(!p||typeof p.id!=='string'||!p.id||ids.has(p.id)||typeof p.name!=='string'||!p.name||p.name.length>200)throw Error('Plano inválido ou duplicado.');ids.add(p.id);
  if(!Number.isInteger(p.year)||!Number.isInteger(p.baseYear)||p.baseYear<2000||p.year>2100||p.baseYear>=p.year||!['Caixa','Competência'].includes(p.regime)||!Array.isArray(p.rows)||p.rows.length>10000)throw Error('Ano, regime ou linhas inválidos.');
  if(p.compareYear!==undefined&&(!Number.isInteger(p.compareYear)||p.compareYear<2000||p.compareYear>=p.baseYear))throw Error('O real anterior deve ser de um ano anterior ao real mais recente.');
  if(p.generationBasis!==undefined&&!['maximum','latest','average','blank'].includes(p.generationBasis))throw Error('Base da sugestão inválida.');
  if(p.marginPercent!==undefined&&(!Number.isFinite(p.marginPercent)||p.marginPercent<0||p.marginPercent>100000))throw Error('Margem inválida.');
  const rowIds=new Set();
  for(const r of p.rows){
   if(!r||typeof r.id!=='string'||rowIds.has(r.id)||['department','package','vbz'].some(k=>typeof r[k]!=='string'||r[k].length>1000)||!Array.isArray(r.months)||r.months.length!==12||r.months.some(v=>v!==null&&(!Number.isSafeInteger(v)||Math.abs(v)>1e14))||typeof(r.note??'')!=='string'||(r.note??'').length>4000)throw Error('Linha de meta inválida.');rowIds.add(r.id);
  }
 }
 return data;
}
async function budgetLoad(){
 budgetLoading=true;
 try{
  if(budgetOffline()){
   const saved=localStorage.getItem('obz-planning-v1');budgetStore=budgetValidate(saved?JSON.parse(saved):budgetClone(planningSeed));
  }else{
   const res=await fetch('/api/planning');const payload=await res.json();if(!res.ok)throw Error(payload.error||'Falha ao carregar metas.');budgetStore=budgetValidate(payload);
  }
  budgetEnsureNextYear();
  budgetId=budgetStore.plans.slice().sort((a,b)=>b.year-a.year)[0]?.id||'';budgetError='';
 }catch(e){budgetError=e.message;}
 budgetLoading=false;if(view==='planning')render();
}
function budgetCurrent(){return budgetStore?.plans.find(p=>p.id===budgetId);}
function budgetEnsureNextYear(){
 const years=[...new Set(db.imports.filter(i=>i.active&&i.regime==='Caixa').map(i=>i.report_year))].sort((a,b)=>b-a);
 if(!years.length||!years.includes(years[0]-1))return;
 const baseYear=years[0],compareYear=baseYear-1,year=baseYear+1;
 if(year>2100||budgetStore.plans.some(p=>p.year===year&&p.regime==='Caixa')||budgetStore.plans.length>=100)return;
 const p={id:budgetUid(),name:'Metas '+year+' · rascunho',year,baseYear,compareYear,regime:'Caixa',generationBasis:'maximum',marginPercent:5,source:'Sugestão das bases reais de Caixa disponíveis',rows:[]};
 const latest=budgetActuals(p,baseYear),previous=budgetActuals(p,compareYear),unique=new Map();
 for(const r of planningSeed.plans[0].rows)unique.set(budgetKey(r),r);
 for(const r of db.entries.filter(r=>!r.issue&&r.regime==='Caixa'&&[compareYear,baseYear].includes(r.report_year)))unique.set(budgetKey(r),r);
 for(const [key,r] of unique)p.rows.push({id:budgetUid(),department:r.department,package:r.package,vbz:r.vbz,months:budgetSuggestion(p,key,'maximum',latest,previous,5,'seasonal'),origins:Array(12).fill('Maior real '+compareYear+' / '+baseYear+' + margem 5%'),note:''});
 budgetValidate({version:1,plans:[...budgetStore.plans,p]});budgetStore.plans.push(p);budgetDirty=true;
}
function budgetPreviousYear(plan){return plan.compareYear??plan.baseYear-1;}
function budgetBasisOptions(plan){return [['maximum','Maior real mensal de '+budgetPreviousYear(plan)+' e '+plan.baseYear+' + margem'],['blank','Preencher metas manualmente']].map(([value,label])=>`<option value="${value}" ${(plan.generationBasis==='blank'?'blank':'maximum')===value?'selected':''}>${label}</option>`).join('');}
function budgetSourceMonths(plan,key,basis,latest,previous){
 if(basis==='blank')return Array(12).fill(null);
 const now=budgetBaseMonths(plan,latest.get(key)||Array(12).fill(0));
 if(basis!=='average'&&basis!=='maximum')return now;
 const coverage=budgetCoverage(plan,budgetPreviousYear(plan)),prior=previous.get(key)||Array(12).fill(0);
 return now.map((v,i)=>v===null||!coverage.has(i)?null:basis==='maximum'?Math.max(0,v,prior[i]):Math.round((v+prior[i])/2));
}
function budgetSuggestion(plan,key,basis,latest,previous,margin,method){
 if(basis==='blank')return Array(12).fill(null);
 if(!Number.isFinite(margin)||margin<0||margin>100000)throw Error('Informe uma margem de 0 a 100.000%.');
 if(basis==='maximum'){
  if(method==='equal')throw Error('Para preservar o maior real de cada mês, use a distribuição pelo mesmo mês.');
  return budgetSourceMonths(plan,key,basis,latest,previous).map(v=>v===null?null:Math.ceil(v*(1+margin/100)));
 }
 return budgetProjection(budgetSourceMonths(plan,key,basis,latest,previous),margin,method);
}
// Aggregates depend only on the loaded entries, never on editable targets.
let budgetEntriesCache=null;
const budgetAggregateCache=new Map();
function budgetAggregate(plan,year){
 if(budgetEntriesCache!==db.entries){budgetEntriesCache=db.entries;budgetAggregateCache.clear();}
 const key=JSON.stringify([plan.regime,year]);
 if(!budgetAggregateCache.has(key)){
  const actual=new Map(),coverage=new Set();
  for(const r of db.entries){
   if(r.issue||r.regime!==plan.regime||r.report_year!==year)continue;
   const key=budgetKey(r),month=Number(r.date.slice(5,7))-1;
   coverage.add(month);if(!actual.has(key))actual.set(key,Array(12).fill(0));
   actual.get(key)[month]+=r.actual;
  }
  budgetAggregateCache.set(key,{actual,coverage});
 }
 return budgetAggregateCache.get(key);
}
function budgetActuals(plan,year){return budgetAggregate(plan,year).actual;}

function budgetHasBase(plan,year){return db.imports.some(i=>i.active&&i.regime===plan.regime&&i.report_year===year);}
function budgetSplit(total){const value=Math.trunc(total/12),rest=total-value*12;return Array.from({length:12},(_,i)=>value+(i<Math.abs(rest)?Math.sign(rest):0));}
function budgetProjection(base,rate,method){
 const target=Math.round(budgetTotal(base)*(1+rate/100));
 if(method==='equal'&&base.some(v=>v===null))throw Error('A base não tem movimentos em todos os meses. Use a distribuição pelo mesmo mês e preencha os meses pendentes.');
 return method==='equal'?budgetSplit(target):base.map(v=>v===null?null:Math.round(v*(1+rate/100)));
}
function budgetCoverage(plan,year){return budgetAggregate(plan,year).coverage;}
function budgetBaseMonths(plan,values){const coverage=budgetCoverage(plan,plan.baseYear);return values.map((v,i)=>coverage.has(i)?v:null);}
function budgetRows(plan){return plan.rows.filter(r=>(!budgetDepartment||normalize(r.department)===normalize(budgetDepartment))&&(!budgetPackage||normalize(r.package)===normalize(budgetPackage))&&(!budgetQuery||normalize(r.vbz+' '+r.department+' '+r.package).includes(normalize(budgetQuery))));}
function budgetPeriod(values){return budgetMonth===''?budgetTotal(values):values[Number(budgetMonth)];}
function budgetMark(){budgetDirty=true;budgetError='';}
function budgetOptions(values,current,first){return (first?'<option value="">'+first+'</option>':'')+values.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(v)}</option>`).join('');}
function budgetMatrix(plan,rows,previous,base){
 const py=budgetPreviousYear(plan),pa=budgetHasBase(plan,py),ba=budgetHasBase(plan,plan.baseYear);
 const indices=budgetMonth===''?Array.from({length:12},(_,i)=>i):[Number(budgetMonth)];
 const part=rows.slice(budgetPage*20,budgetPage*20+20);
 const money=(values,available)=>available?brl(budgetPeriod(values||Array(12).fill(0))):'—';
 return `<div class="budget-matrix" tabindex="0" role="region" aria-label="Planejamento mensal por departamento, pacote e despesa"><table><thead><tr><th rowspan="2" class="matrix-department">Departamento</th><th rowspan="2" class="matrix-package">Pacote</th><th rowspan="2" class="matrix-vbz">Despesa (VBZ)</th>${indices.map(i=>`<th colspan="3" class="matrix-month">${months[i]}</th>`).join('')}<th colspan="3" class="matrix-month">${budgetMonth===''?'Total anual':'Total do período'}</th><th rowspan="2">Detalhar</th></tr><tr>${[...indices,'total'].map(()=>`<th>Real ${py}</th><th>Real ${plan.baseYear}</th><th class="matrix-target">Meta ${plan.year}</th>`).join('')}</tr></thead><tbody>${part.map((r,index)=>{
 const before=previous.get(budgetKey(r))||Array(12).fill(0),now=base.get(budgetKey(r))||Array(12).fill(0),newDepartment=index===0||part[index-1].department!==r.department;
 return `<tr class="${newDepartment?'matrix-group':''}"><td class="matrix-department">${esc(r.department)}</td><td class="matrix-package">${esc(r.package)}</td><td class="matrix-vbz">${esc(r.vbz)}</td>${indices.map(i=>`<td class="num">${pa?brl(before[i]):'—'}</td><td class="num">${ba?brl(now[i]):'—'}</td><td class="matrix-target"><input type="number" step="0.01" aria-label="Meta ${months[i]} · ${esc(r.department)} · ${esc(r.vbz)}" data-matrix-row="${esc(r.id)}" data-matrix-month="${i}" value="${r.months[i]===null?'':r.months[i]/100}" placeholder="Pendente"></td>`).join('')}<td class="num">${money(before,pa)}</td><td class="num">${money(now,ba)}</td><td class="num matrix-target" data-matrix-row-total="${esc(r.id)}">${budgetMatrixTotal(r,indices)}</td><td><button class="reset" data-budget-edit="${esc(r.id)}">Detalhar / editar</button></td></tr>`;
 }).join('')||`<tr><td colspan="${7+indices.length*3}" class="empty">Nenhuma despesa para estes filtros.</td></tr>`}</tbody><tfoot><tr><th colspan="3" class="matrix-total-label">Total das ${rows.length} linhas filtradas</th>${indices.map(i=>`<td class="num">${pa?brl(rows.reduce((s,r)=>s+(previous.get(budgetKey(r))?.[i]||0),0)):'—'}</td><td class="num">${ba?brl(rows.reduce((s,r)=>s+(base.get(budgetKey(r))?.[i]||0),0)):'—'}</td><td class="num matrix-target" data-matrix-month-total="${i}">${budgetMatrixFooter(rows,[i])}</td>`).join('')}<td class="num">${pa?brl(rows.reduce((s,r)=>s+budgetPeriod(previous.get(budgetKey(r))||Array(12).fill(0)),0)):'—'}</td><td class="num">${ba?brl(rows.reduce((s,r)=>s+budgetPeriod(base.get(budgetKey(r))||Array(12).fill(0)),0)):'—'}</td><td class="num matrix-target" id="matrixGrandTotal">${budgetMatrixFooter(rows,indices)}</td><td></td></tr></tfoot></table></div>`;
}
function budgetMatrixTotal(row,indices){return brl(indices.reduce((s,i)=>s+(row.months[i]??0),0))+(indices.some(i=>row.months[i]===null)?'<small class="detail">Parcial</small>':'');}
function budgetMatrixFooter(rows,indices){return brl(rows.reduce((s,r)=>s+indices.reduce((a,i)=>a+(r.months[i]??0),0),0))+(rows.some(r=>indices.some(i=>r.months[i]===null))?'<small class="detail">Parcial</small>':'');}
function budgetMatrixRefresh(){
 const p=budgetCurrent(),rows=budgetRows(p),indices=budgetMonth===''?Array.from({length:12},(_,i)=>i):[Number(budgetMonth)];
 document.querySelectorAll('[data-matrix-row-total]').forEach(cell=>{const row=p.rows.find(r=>r.id===cell.dataset.matrixRowTotal);cell.innerHTML=budgetMatrixTotal(row,indices);});
 document.querySelectorAll('[data-matrix-month-total]').forEach(cell=>cell.innerHTML=budgetMatrixFooter(rows,[Number(cell.dataset.matrixMonthTotal)]));
 if($('matrixGrandTotal'))$('matrixGrandTotal').innerHTML=budgetMatrixFooter(rows,indices);
 const cards=document.querySelectorAll('.budget-cards .card'),target=rows.reduce((s,r)=>s+budgetPeriod(r.months),0),pending=rows.reduce((s,r)=>s+indices.filter(i=>r.months[i]===null).length,0),actual=budgetActuals(p,p.year),spent=rows.reduce((s,r)=>s+budgetPeriod(actual.get(budgetKey(r))||Array(12).fill(0)),0),d=budgetDelta(spent,target,budgetHasBase(p,p.year)&&!pending);
 cards[2].querySelector('strong').textContent=brl(target);cards[2].querySelector('small').textContent=pending?integer(pending)+' metas mensais pendentes':'Metas preenchidas no período';
 cards[4].querySelector('strong').textContent=d.amount===null?'—':brl(d.amount);cards[5].querySelector('strong').textContent=budgetPercent(d.percent);
 for(const card of [cards[4],cards[5]])card.querySelector('strong').className=d.amount>0?'bad':d.amount<0?'good':'';
 document.querySelector('.budget-save').textContent='Alterações ainda não salvas.';
 // Keep the consolidated monthly view in sync without moving the horizontal scroll.
 const distribution=$('budgetDistribution');if(distribution)distribution.style.display='none';
}
function planningView(){
 if(!budgetStore){if(!budgetLoading&&!budgetError){budgetLoading=true;queueMicrotask(()=>void budgetLoad());}return `<section class="panel"><h2>Planejamento de metas</h2><p>${budgetError?esc(budgetError):'Carregando planejamentos…'}</p>${budgetError?'<button id="budgetRetry" class="secondary">Tentar novamente</button>':''}</section>`;}
 const p=budgetCurrent();
 if(!p)return '<section class="panel"><button id="budgetNew" class="primary">Criar planejamento</button></section>';
 const previousYear=budgetPreviousYear(p),previous=budgetActuals(p,previousYear),previousAvailable=budgetHasBase(p,previousYear);
 const base=budgetActuals(p,p.baseYear),actual=budgetActuals(p,p.year),baseAvailable=budgetHasBase(p,p.baseYear),actualAvailable=budgetHasBase(p,p.year),rows=budgetRows(p);
 const previousTotal=rows.reduce((s,r)=>s+budgetPeriod(previous.get(budgetKey(r))||Array(12).fill(0)),0);
 const baseline=rows.reduce((s,r)=>s+budgetPeriod(base.get(budgetKey(r))||Array(12).fill(0)),0),target=rows.reduce((s,r)=>s+budgetPeriod(r.months),0),spent=rows.reduce((s,r)=>s+budgetPeriod(actual.get(budgetKey(r))||Array(12).fill(0)),0);
 const indexes=budgetMonth===''?Array.from({length:12},(_,i)=>i):[Number(budgetMonth)];
 const pending=rows.reduce((s,r)=>s+indexes.filter(i=>r.months[i]===null).length,0);
 const rowKeys=new Set(p.rows.map(budgetKey)),unplanned=[...actual].filter(([key])=>!rowKeys.has(key)),outside=unplanned.reduce((s,[key,values])=>s+budgetPeriod(values),0);
 budgetPage=Math.max(0,Math.min(budgetPage,Math.ceil(rows.length/20)-1));
 return `<section class="panel budget-toolbar"><div class="budget-controls"><label>Planejamento<select id="budgetSelect">${budgetStore.plans.map(v=>`<option value="${esc(v.id)}" ${v.id===p.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><button id="budgetNew" class="secondary">Novo planejamento</button><button id="budgetSave" class="primary" ${budgetSaving?'disabled':''}>${budgetSaving?'Salvando…':'Salvar metas'}</button><button id="budgetBackup" class="secondary">Baixar backup</button><label class="secondary budget-file">Abrir backup<input id="budgetRestore" type="file" accept=".json,application/json"></label><button id="budgetCSV" class="secondary">Exportar CSV</button></div><p class="budget-save" role="status">${budgetError?esc(budgetError):budgetDirty?'Alterações ainda não salvas.':budgetOffline()?'Salvamento neste navegador. Use Baixar backup para levar as metas a outro computador.':'Metas carregadas. Use Salvar metas após editar.'}</p></section>
 <section class="panel"><div class="budget-controls"><div><div class="eyebrow">PLANEJAMENTO ${p.year}</div><h2>${esc(p.name)}</h2></div><label>Comparar realizado em<select id="budgetRegime">${budgetOptions(['Caixa','Competência'],p.regime)}</select></label><label>Departamento<select id="budgetDepartment">${budgetOptions([...new Set(p.rows.map(r=>r.department))].sort(),budgetDepartment,'Todos')}</select></label><label>Pacote<select id="budgetPackage">${budgetOptions([...new Set(p.rows.map(r=>r.package))].sort(),budgetPackage,'Todos')}</select></label><label>Período<select id="budgetMonth"><option value="">Ano completo</option>${months.map((m,i)=>`<option value="${i}" ${String(i)===budgetMonth?'selected':''}>${m}</option>`).join('')}</select></label></div><p class="detail">Histórico real: ${previousYear} e ${p.baseYear} · Realizado da base, sem expurgos.${p.imported?' Metas de 2026: valores salvos no Excel; células sem preenchimento permanecem pendentes.':''}</p><p class="detail">Real ${previousYear}: ${budgetCoverage(p,previousYear).size}/12 meses com movimentos · Real ${p.baseYear}: ${budgetCoverage(p,p.baseYear).size}/12 meses com movimentos. Ao gerar metas, meses sem movimentos na base ficam pendentes.</p></section>
 <div class="cards budget-cards"><article class="card"><div class="label">Realizado ${previousYear}</div><strong>${previousAvailable?brl(previousTotal):'—'}</strong><small>Primeiro ano do histórico</small></article><article class="card"><div class="label">Realizado ${p.baseYear}</div><strong>${baseAvailable?brl(baseline):'—'}</strong><small>Período selecionado · linhas do planejamento</small></article><article class="card featured"><div class="label">Meta ${p.year}</div><strong>${brl(target)}</strong><small>${pending?integer(pending)+' metas mensais pendentes':'Metas preenchidas no período'}</small></article><article class="card"><div class="label">Realizado ${p.year}</div><strong>${actualAvailable?brl(spent):'—'}</strong><small>Mesmo período e categorias</small></article><article class="card"><div class="label">Delta (R$)</div><strong class="${spent>target?'bad':'good'}">${actualAvailable&&!pending?brl(spent-target):'—'}</strong><small>${pending?'Preencha as metas para apurar o delta':'Positivo: acima da meta'}</small></article><article class="card"><div class="label">Delta (%)</div><strong class="${spent>target?'bad':'good'}">${budgetPercent(budgetDelta(spent,target,actualAvailable&&!pending).percent)}</strong><small>Realizado menos meta, dividido pela meta</small></article></div>
 ${outside?`<p class="notice">${brl(outside)} de realizado em categorias fora deste planejamento (todos os departamentos). <button id="budgetAddMissing" class="reset">Incluir categorias sem meta</button></p>`:''}
 <section class="panel"><div class="budget-controls"><label>Buscar despesa<input id="budgetSearch" type="search" placeholder="Descrição VBZ, departamento ou pacote" value="${esc(budgetQuery)}"></label><label>Sugestão inicial<select id="budgetBasis">${budgetBasisOptions(p)}</select></label><label>Margem de segurança (%)<input id="budgetRate" type="number" step="0.1" min="0" max="100000" value="${p.marginPercent??5}"></label><label>Distribuição<select id="budgetMethod"><option value="seasonal">Preservar o mesmo mês dos anos reais</option></select></label><button id="budgetApply" class="secondary" ${!baseAvailable?'disabled':''}>Gerar metas nas ${rows.length} linhas filtradas</button></div><p class="detail">Gerar metas substitui os 12 meses das linhas filtradas. Sugestão: maior real mensal dos dois anos + margem. Você pode digitar outro valor, inclusive menor, em Detalhar / editar.</p>
 <div class="budget-layout-controls"><label>Visualização<select id="budgetLayout"><option value="monthly" ${budgetLayout==='monthly'?'selected':''}>Mensal por departamento e VBZ</option><option value="summary" ${budgetLayout==='summary'?'selected':''}>Resumo do período e deltas</option></select></label><p class="detail">Na visão mensal, edite as metas diretamente nas células destacadas. Deslize a tabela para ver os outros meses.</p></div>
 ${budgetLayout==='monthly'?budgetMatrix(p,rows,previous,base):table(['Departamento / pacote','Despesa (VBZ)','Real '+previousYear,'Real '+p.baseYear,'Variação histórica','Meta '+p.year,'Realizado '+p.year,'Delta (R$)','Delta (%)','Editar'],rows.slice(budgetPage*20,budgetPage*20+20).map(r=>{
 const prior=budgetPeriod(previous.get(budgetKey(r))||Array(12).fill(0)),b=budgetPeriod(base.get(budgetKey(r))||Array(12).fill(0)),a=budgetPeriod(actual.get(budgetKey(r))||Array(12).fill(0)),t=budgetPeriod(r.months),missing=indexes.some(i=>r.months[i]===null);
 return `<tr><td>${esc(r.department)}<div class="detail">${esc(r.package)}</div></td><td>${esc(r.vbz)}${r.note?'<div class="detail">'+esc(r.note)+'</div>':''}</td><td class="num">${previousAvailable?brl(prior):'—'}</td><td class="num">${baseAvailable?brl(b):'—'}</td><td class="num">${previousAvailable&&baseAvailable?brl(b-prior):'—'}</td><td class="num">${brl(t)}${missing?'<div class="detail">Preenchimento parcial</div>':''}</td><td class="num">${actualAvailable?brl(a):'—'}</td>${budgetDeltaCells(a,t,actualAvailable&&!missing)}<td><button class="reset" data-budget-edit="${esc(r.id)}">Detalhar / editar</button></td></tr>`;
 }))}<div class="pagination"><span>${rows.length} linhas · Página ${budgetPage+1} de ${Math.max(1,Math.ceil(rows.length/20))}</span><div><button id="budgetPrev" ${budgetPage===0?'disabled':''}>Anterior</button><button id="budgetNext" ${(budgetPage+1)*20>=rows.length?'disabled':''}>Próxima</button></div></div></section>
 <section class="panel" id="budgetDistribution" style="display:${budgetLayout==='monthly'?'none':''}"><h2>Distribuição mensal</h2>${table(['Mês','Real '+previousYear,'Real '+p.baseYear,'Meta '+p.year,'Realizado '+p.year,'Delta (R$)','Delta (%)'],months.map((m,i)=>{const t=rows.reduce((s,r)=>s+(r.months[i]??0),0),a=rows.reduce((s,r)=>s+(actual.get(budgetKey(r))?.[i]||0),0),missing=rows.some(r=>r.months[i]===null);return `<tr><td>${m}</td><td>${previousAvailable?brl(rows.reduce((s,r)=>s+(previous.get(budgetKey(r))?.[i]||0),0)):'—'}</td><td>${baseAvailable?brl(rows.reduce((s,r)=>s+(base.get(budgetKey(r))?.[i]||0),0)):'—'}</td><td>${brl(t)}${missing?' (parcial)':''}</td><td>${actualAvailable?brl(a):'—'}</td>${budgetDeltaCells(a,t,actualAvailable&&!missing)}</tr>`;}))}</section>
 <dialog id="budgetDialog" class="budget-dialog"></dialog>`;
}
function budgetDialog(html){$('budgetDialog').innerHTML=html;$('budgetDialog').showModal();$('budgetClose').onclick=()=>$('budgetDialog').close();}
function budgetEdit(id){
 const p=budgetCurrent(),previousYear=budgetPreviousYear(p),previous=budgetActuals(p,previousYear),row=p.rows.find(r=>r.id===id),base=budgetActuals(p,p.baseYear).get(budgetKey(row))||Array(12).fill(0),actual=budgetActuals(p,p.year).get(budgetKey(row))||Array(12).fill(0);
 budgetDialog(`<form id="budgetEditForm"><button id="budgetClose" type="button" class="close" aria-label="Fechar">×</button><h2>${esc(row.vbz)}</h2><p>${esc(row.department)} · ${esc(row.package)}</p>${table(['Mês','Real '+previousYear,'Real '+p.baseYear,'Meta '+p.year,'Realizado '+p.year,'Delta (R$)','Delta (%)'],months.map((m,i)=>`<tr><td>${m}</td><td>${budgetHasBase(p,previousYear)?brl(previous.get(budgetKey(row))?.[i]||0):'—'}</td><td>${budgetHasBase(p,p.baseYear)?brl(base[i]):'—'}</td><td><input aria-label="Meta ${m}" class="budget-money" type="number" step="0.01" data-budget-month="${i}" value="${row.months[i]===null?'':row.months[i]/100}"><small class="detail">${esc(row.origins?.[i]||'Meta planejada')}</small></td><td>${budgetHasBase(p,p.year)?brl(actual[i]):'—'}</td>${budgetDeltaCells(actual[i],row.months[i],budgetHasBase(p,p.year))}</tr>`))}<label>Justificativa<textarea id="budgetNote" maxlength="4000">${esc(row.note||'')}</textarea></label><p class="detail">Campo vazio: meta pendente. Zero: meta de R$ 0,00.</p><button class="primary" type="submit">Aplicar edição</button></form>`);
 document.querySelectorAll('[data-budget-month]').forEach(input=>input.oninput=()=>{
  const i=Number(input.dataset.budgetMonth),target=input.value===''||!input.validity.valid?null:Math.round(Number(input.value)*100),delta=budgetDelta(actual[i],target,budgetHasBase(p,p.year)),cells=input.closest('tr').cells;
  cells[5].textContent=delta.amount===null?'—':brl(delta.amount);cells[6].textContent=budgetPercent(delta.percent);
  for(const cell of [cells[5],cells[6]])cell.className='num '+(delta.amount>0?'bad':delta.amount<0?'good':'');
 });
 $('budgetEditForm').onsubmit=e=>{e.preventDefault();const values=[...document.querySelectorAll('[data-budget-month]')].map(input=>input.value===''?null:Math.round(Number(input.value)*100));if(values.some(v=>v!==null&&(!Number.isSafeInteger(v)||Math.abs(v)>1e14)))return;
 row.origins=values.map((v,i)=>v===row.months[i]?(row.origins?.[i]||'Meta planejada'):'Editado no planejamento');row.months=values;row.note=$('budgetNote').value;budgetMark();$('budgetDialog').close();render();};
}
function budgetCreate(){
 const years=[...new Set(db.imports.filter(i=>i.active).map(i=>i.report_year))].sort((a,b)=>b-a);
 budgetDialog(`<form id="budgetCreateForm"><button id="budgetClose" type="button" class="close" aria-label="Fechar">×</button><h2>Novo planejamento</h2><label>Nome<input id="budgetName" required maxlength="200" value="Metas ${years[0]+1}"></label><div class="formrow"><label>Ano da meta<input id="budgetYear" required type="number" min="2001" max="2100" value="${years[0]+1}"></label><label>Real mais recente<select id="budgetBase">${budgetOptions(years,years[0])}</select></label><label>Real anterior<select id="budgetCompare">${budgetOptions(years,years[0]-1)}</select></label></div><label>Regime<select id="budgetCreateRegime">${budgetOptions(['Caixa','Competência'],'Caixa')}</select></label><label>Sugestão inicial<select id="budgetCreateBasis">${budgetBasisOptions({baseYear:years[0],compareYear:years[0]-1})}</select></label><label>Margem de segurança (%)<input id="budgetCreateRate" type="number" step="0.1" min="0" max="100000" value="5" required></label><label>Distribuição<select id="budgetCreateMethod"><option value="seasonal">Preservar o mesmo mês dos anos reais</option></select></label><p id="budgetCreateError" role="status"></p><button class="primary" type="submit">Criar metas</button></form>`);
 const updateBasis=()=>{$('budgetCreateBasis').innerHTML=budgetBasisOptions({baseYear:Number($('budgetBase').value),compareYear:Number($('budgetCompare').value),generationBasis:$('budgetCreateBasis').value});};
 $('budgetBase').onchange=()=>{const prior=Number($('budgetBase').value)-1;if(years.includes(prior))$('budgetCompare').value=String(prior);updateBasis();};
 $('budgetCompare').onchange=updateBasis;
 $('budgetYear').onchange=()=>{const year=Number($('budgetYear').value);if(years.includes(year-1))$('budgetBase').value=String(year-1);if(years.includes(year-2))$('budgetCompare').value=String(year-2);updateBasis();};
 $('budgetCreateForm').onsubmit=e=>{e.preventDefault();try{
 const p={id:budgetUid(),name:$('budgetName').value.trim(),year:Number($('budgetYear').value),baseYear:Number($('budgetBase').value),compareYear:Number($('budgetCompare').value),generationBasis:$('budgetCreateBasis').value,marginPercent:Number($('budgetCreateRate').value),regime:$('budgetCreateRegime').value,source:'Realizado da base local, sem expurgos',rows:[]};
 if(!p.name||p.compareYear>=p.baseYear||p.baseYear>=p.year||!budgetHasBase(p,p.baseYear)||!budgetHasBase(p,p.compareYear))throw Error('Importe os dois anos reais no mesmo regime e selecione anos históricos anteriores à meta.');
 const base=budgetActuals(p,p.baseYear),previous=budgetActuals(p,p.compareYear),unique=new Map();
 for(const r of planningSeed.plans[0].rows)unique.set(budgetKey(r),r);
 for(const r of db.entries.filter(r=>!r.issue&&r.regime===p.regime&&[p.compareYear,p.baseYear].includes(r.report_year)))unique.set(budgetKey(r),r);
 for(const [key,r] of unique){p.rows.push({id:budgetUid(),department:r.department,package:r.package,vbz:r.vbz,months:budgetSuggestion(p,key,p.generationBasis,base,previous,p.marginPercent,$('budgetCreateMethod').value),note:'',origins:Array(12).fill(p.generationBasis==='blank'?'Preenchimento manual':'Maior real '+p.compareYear+' / '+p.baseYear+' + margem '+p.marginPercent+'%')});}
 budgetValidate({version:1,plans:[...budgetStore.plans,p]});budgetStore.plans.push(p);budgetId=p.id;budgetDepartment=budgetPackage=budgetQuery=budgetMonth='';budgetPage=0;budgetMark();$('budgetDialog').close();render();
 }catch(error){$('budgetCreateError').textContent=error.message;}};
}
async function budgetSave(){
 const invalid=[...document.querySelectorAll('[data-matrix-row]')].find(input=>!input.validity.valid);if(invalid){invalid.reportValidity();return;}
 if(budgetSaving)return;budgetSaving=true;budgetError='';render();
 try{const snapshot=budgetValidate(budgetClone(budgetStore));
  if(budgetOffline()){localStorage.setItem('obz-planning-v1',JSON.stringify(snapshot));}
  else{const res=await fetch('/api/planning',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});const value=await res.json();if(!res.ok)throw Error(value.error||'Falha ao salvar.');budgetStore.revision=value.revision;snapshot.revision=value.revision;}
  budgetDirty=JSON.stringify(budgetStore)!==JSON.stringify(snapshot);
 }catch(e){budgetError='Não foi possível salvar: '+e.message+' Baixe um backup para preservar suas alterações.';}
 budgetSaving=false;render();
}
function budgetDownload(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function budgetCSV(){
 const p=budgetCurrent(),previousYear=budgetPreviousYear(p),previous=budgetActuals(p,previousYear),base=budgetActuals(p,p.baseYear),actual=budgetActuals(p,p.year);
 const lines=[['Ano meta','Real anterior (ano)','Real recente (ano)','Regime','Departamento','Pacote','VBZ','Mês','Real '+previousYear,'Real '+p.baseYear,'Meta','Realizado ano meta','Delta (R$)','Delta (%)','Justificativa']];
 const number=value=>value===null?'':value.toFixed(2).replace('.',',');
 for(const r of budgetRows(p))for(let i=0;i<12;i++){
  const a=actual.get(budgetKey(r))?.[i]||0,d=budgetDelta(a,r.months[i],budgetHasBase(p,p.year));
  lines.push([p.year,previousYear,p.baseYear,p.regime,r.department,r.package,r.vbz,i+1,budgetHasBase(p,previousYear)?number((previous.get(budgetKey(r))?.[i]||0)/100):'',budgetHasBase(p,p.baseYear)?number((base.get(budgetKey(r))?.[i]||0)/100):'',r.months[i]===null?'':number(r.months[i]/100),budgetHasBase(p,p.year)?number(a/100):'',d.amount===null?'':number(d.amount/100),number(d.percent),r.note||'']);
 }
 const cell=v=>classifyCSV(v);
 budgetDownload('\ufeff'+lines.map(line=>line.map(cell).join(';')).join('\r\n'),'metas-'+p.year+'.csv','text/csv;charset=utf-8');
}
function classifyCSV(value){const text=String(value),safe=/^[=+@-]/.test(text)&&!/^[-+]?\d+(?:,\d+)?$/.test(text)?"'"+text:text;return '"'+safe.replace(/"/g,'""')+'"';}
function bindPlanning(){
 const bind=(id,event,fn)=>{if($(id))$(id)[event]=fn;};
 bind('budgetRetry','onclick',()=>{budgetError='';void budgetLoad();});
 bind('budgetSelect','onchange',e=>{budgetId=e.target.value;budgetDepartment=budgetPackage=budgetQuery='';budgetPage=0;render();});
 bind('budgetNew','onclick',budgetCreate);bind('budgetSave','onclick',budgetSave);
 bind('budgetBackup','onclick',()=>budgetDownload(JSON.stringify(budgetStore,null,2),'backup-metas-obz.json','application/json'));
 bind('budgetRestore','onchange',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Backup deve ter até 10 MB.');const imported=budgetValidate(JSON.parse(await file.text()));if(budgetStore.plans.length+imported.plans.length>100)throw Error('Limite de 100 planejamentos.');for(const p of imported.plans){const copy=budgetClone(p);copy.id=budgetUid();copy.name=(copy.name+' · backup').slice(0,200);budgetStore.plans.push(copy);budgetId=copy.id;}budgetMark();render();}catch(error){budgetError=error.message;render();}});
 bind('budgetRegime','onchange',e=>{budgetCurrent().regime=e.target.value;budgetMark();render();});
 bind('budgetDepartment','onchange',e=>{budgetDepartment=e.target.value;budgetPage=0;render();});bind('budgetPackage','onchange',e=>{budgetPackage=e.target.value;budgetPage=0;render();});bind('budgetMonth','onchange',e=>{budgetMonth=e.target.value;render();});
 bind('budgetSearch','oninput',e=>{const position=e.target.selectionStart;budgetQuery=e.target.value;budgetPage=0;scheduleSearchRender('budgetSearch');});
 bind('budgetLayout','onchange',e=>{budgetLayout=e.target.value;render();});
 document.querySelectorAll('[data-matrix-row]').forEach(input=>input.oninput=()=>{
  const value=input.value===''?null:Math.round(Number(input.value)*100);
  if(input.validity.badInput||value!==null&&(!Number.isSafeInteger(value)||Math.abs(value)>1e14)){input.setCustomValidity('Informe um valor monetário válido.');return;}
  input.setCustomValidity('');const row=budgetCurrent().rows.find(r=>r.id===input.dataset.matrixRow),i=Number(input.dataset.matrixMonth);
  if(row.months[i]!==value){row.months[i]=value;row.origins=row.origins||Array(12).fill('Meta planejada');row.origins[i]='Editado na distribuição mensal';budgetMark();budgetMatrixRefresh();}
 });
 bind('budgetPrev','onclick',()=>{budgetPage--;render();});bind('budgetNext','onclick',()=>{budgetPage++;render();});bind('budgetCSV','onclick',budgetCSV);
 bind('budgetApply','onclick',()=>{const p=budgetCurrent(),base=budgetActuals(p,p.baseYear),rate=Number($('budgetRate').value),method=$('budgetMethod').value,basis=$('budgetBasis').value,previous=budgetActuals(p,budgetPreviousYear(p));try{if(!Number.isFinite(rate)||rate<0||rate>100000)throw Error('Informe uma margem de 0 a 100.000%.');if(basis!=='blank'&&!budgetHasBase(p,budgetPreviousYear(p)))throw Error('Importe os dois anos reais para gerar a sugestão com margem.');const generated=budgetRows(p).map(r=>[r,budgetSuggestion(p,budgetKey(r),basis,base,previous,rate,method)]);for(const [r,values] of generated){r.months=values;r.origins=Array(12).fill(basis==='blank'?'Preenchimento manual':'Maior real '+budgetPreviousYear(p)+' / '+p.baseYear+' + margem '+rate+'%');}p.generationBasis=basis;p.marginPercent=rate;budgetMark();}catch(e){budgetError=e.message;}render();});
 bind('budgetAddMissing','onclick',()=>{const p=budgetCurrent(),keys=new Set(p.rows.map(budgetKey));for(const r of db.entries.filter(r=>!r.issue&&r.regime===p.regime&&r.report_year===p.year)){const key=budgetKey(r);if(!keys.has(key)){keys.add(key);p.rows.push({id:budgetUid(),department:r.department,package:r.package,vbz:r.vbz,months:Array(12).fill(null),note:''});}}budgetMark();render();});
 document.querySelectorAll('[data-budget-edit]').forEach(b=>b.onclick=()=>budgetEdit(b.dataset.budgetEdit));
}
window.addEventListener('beforeunload',e=>{if(budgetDirty){e.preventDefault();e.returnValue='';}});

// Adaptador exclusivo da publicação estática; o sistema local continua editável.
let publishedSnapshot;
async function publishedData(){
 if(!publishedSnapshot)publishedSnapshot=(async()=>{
  const response=await fetch('atualizacao.json?t='+Date.now(),{cache:'no-store'});
  if(!response.ok)throw Error('Não foi possível consultar a atualização publicada.');
  const manifest=await response.json();
  const dataResponse=await fetch(manifest.data,{cache:'no-store'});
  if(!dataResponse.ok)throw Error('Não foi possível carregar os dados publicados.');
  const snapshot=await dataResponse.json();
  if(snapshot.entryFiles){
   const parts=await Promise.all(snapshot.entryFiles.map(async file=>{
    const response=await fetch(file,{cache:'no-store'});
    if(!response.ok)throw Error('Não foi possível carregar os lançamentos publicados.');
    return response.json();
   }));
   snapshot.entries=parts.flat();
  }
  snapshot.documentEntryIds=new Set(snapshot.documentEntryIds);
  document.querySelector('.sidebottom small').textContent='Atualizado em '+new Date(manifest.updatedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
  return snapshot;
 })().catch(error=>{publishedSnapshot=null;throw error;});
 return publishedSnapshot;
}
budgetLoad=async function(){
 budgetLoading=true;
 try{
  const snapshot=await publishedData();
  budgetStore=budgetValidate(budgetClone(snapshot.planning));
  budgetId=budgetStore.plans.slice().sort((a,b)=>b.year-a.year)[0]?.id||'';
  budgetError='';
 }catch(error){budgetError=error.message;}
 budgetLoading=false;if(view==='planning')render();
};
budgetMark=function(){};
budgetSave=async function(){};
budgetCreate=function(){};
const publishedBindPlanning=bindPlanning;
bindPlanning=function(){
 publishedBindPlanning();
 for(const id of ['budgetNew','budgetSave','budgetBackup','budgetAddMissing','budgetApply'])document.getElementById(id)?.remove();
 document.getElementById('budgetRestore')?.closest('label').remove();
 for(const id of ['budgetBasis','budgetRate','budgetMethod'])document.getElementById(id)?.closest('label').remove();
 document.querySelectorAll('[data-matrix-row]').forEach(input=>{input.readOnly=true;input.oninput=null;});
 document.querySelectorAll('[data-budget-edit]').forEach(button=>button.textContent='Detalhar');
 const status=document.querySelector('.budget-save');if(status)status.textContent='Metas publicadas · somente consulta';
 document.querySelectorAll('.budget-layout-controls .detail').forEach(p=>p.textContent='Deslize a tabela para consultar os outros meses.');
 const search=document.getElementById('budgetSearch');
 if(search){const detail=search.closest('.budget-controls').nextElementSibling;if(detail?.classList.contains('detail'))detail.remove();}
};
const publishedBudgetEdit=budgetEdit;
budgetEdit=function(id){
 publishedBudgetEdit(id);
 document.querySelectorAll('#budgetDialog input,#budgetDialog textarea').forEach(input=>{input.readOnly=true;input.oninput=null;});
 document.querySelector('#budgetEditForm [type=submit]')?.remove();
 document.getElementById('budgetEditForm').onsubmit=event=>event.preventDefault();
};

const $=id=>document.getElementById(id);
const currencyFormatter=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:2});
const brl=c=>currencyFormatter.format(c/100);
const integerFormatter=new Intl.NumberFormat('pt-BR');
const integer=n=>integerFormatter.format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateBR=value=>String(value??'').replace(/^(\d{4})-(\d{2})-(\d{2})(?=$|T| )/,'$3/$2/$1').replace('T',' ');
const months=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
let db={entries:[],imports:[]},view='dashboard',page=0,search='';
const size=40;
const sum=(rs,k='actual')=>rs.reduce((s,r)=>s+r[k],0);
function options(id,values,first){const prior=$(id).value;$(id).innerHTML=(first?`<option value="">${first}</option>`:'')+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(values.map(String).includes(prior))$(id).value=prior;}
async function load(){db=await publishedData();const years=[...new Set(db.imports.filter(i=>i.active).map(i=>i.report_year))].sort((a,b)=>b-a);options('year',years);options('department',[...new Set(db.entries.map(r=>r.department))].sort(),'Todos os departamentos');options('package',[...new Set(db.entries.map(r=>r.package))].sort(),'Todos os pacotes');accountOptions();render();}
function selected(r,year,valid=true){return r.regime===$('regime').value&&r.report_year===year&&(!valid||!r.issue)&&(!$('month').value||r.date.slice(5,7)===$('month').value)&&(!$('department').value||r.department===$('department').value)&&(!$('package').value||r.package===$('package').value)&&matchesAccount(r);}
function grouped(rs,key){const map=new Map();for(const r of rs)map.set(r[key],(map.get(r[key])||0)+r.actual);return [...map].sort((a,b)=>b[1]-a[1]);}

const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
function matchesAccount(r){const q=normalize($('account').value);if(!q)return true;if(q.includes(' · '))return r.account===q.split(' · ')[0];return normalize(r.account+' '+r.vbz).includes(q);}
function accountOptions(){
 const rows=db.entries.filter(r=>r.regime===$('regime').value&&[Number($('year').value),Number($('year').value)-1].includes(r.report_year)&&(!$('department').value||r.department===$('department').value)&&(!$('package').value||r.package===$('package').value));
 const labels=new Map();for(const r of rows){if(!labels.has(r.account))labels.set(r.account,r.vbz);}
 $('accounts').innerHTML=[...labels].sort((a,b)=>Number(a[0])-Number(b[0])).map(([code,name])=>`<option value="${esc(code+' · '+name)}"></option>`).join('');
}
function accountsTable(rs,old,year,available,priorAvailable){
 const current=new Map(grouped(rs,'account')),prior=new Map(grouped(old,'account'));
 const labels=new Map([...old,...rs].map(r=>[r.account,r.vbz]));
 const codes=[...new Set([...current.keys(),...prior.keys()])].sort((a,b)=>(current.get(b)||0)-(current.get(a)||0)||Number(a)-Number(b));
 return `<section class="panel tablepanel"><div class="tablehead"><div><h2>Comparação por conta gerencial</h2><p class="intro">${integer(codes.length)} contas · mesmos filtros e período nos dois anos. Clique na conta para atualizar o painel.</p></div></div>${table(['Conta / descrição',String(year-1),String(year),'Diferença em R$','Variação','Detalhar'],codes.map(code=>{
 const now=current.get(code)||0,before=prior.get(code)||0,comparable=available&&priorAvailable;
 const variation=comparable&&before?((now-before)/Math.abs(before)*100):null;
 return `<tr><td><button class="accountlink" data-account="${esc(code)}">${esc(code)} · ${esc(labels.get(code))}</button></td><td class="num">${priorAvailable?brl(before):'—'}</td><td class="num">${available?brl(now):'—'}</td><td class="num">${comparable?brl(now-before):'—'}</td><td class="num">${variation===null?'—':(variation>0?'+':'')+variation.toFixed(1).replace('.',',')+'%'}</td><td class="num"><button class="reset" data-account-entries="${esc(code)}">Lançamentos ↗</button></td></tr>`;
 }).concat(codes.length?[`<tr class="totals"><td>Total</td><td class="num">${priorAvailable?brl(sum(old)):'—'}</td><td class="num">${available?brl(sum(rs)):'—'}</td><td class="num">${available&&priorAvailable?brl(sum(rs)-sum(old)):'—'}</td><td></td><td></td></tr>`]:[]))}<p class="detail">Zero indica ausência de movimento para a conta na base e nos filtros selecionados. Traço indica base de comparação indisponível ou percentual sem valor anterior.</p></section>`;
}

function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map((h,i)=>`<th${i===headers.length-1?' class="num"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">Nenhum movimento encontrado para estes filtros.</td></tr>`}</tbody></table></div>`;}
let searchRenderTimer=null;
function scheduleSearchRender(id){
 clearTimeout(searchRenderTimer);
 const field=$(id),start=field.selectionStart,end=field.selectionEnd;
 searchRenderTimer=setTimeout(()=>{
  const focused=document.activeElement===field;
  render();
  if(focused&&$(id)){$(id).focus();$(id).setSelectionRange(start,end);}
 },150);
}
function render(){
 clearTimeout(searchRenderTimer);
 document.querySelector('.filters').style.display=view==='planning'?'none':'';
 $('uploadButton').style.display=view==='planning'?'none':'';
 if(view==='planning'){
  $('title').textContent='Planejamento de metas';
  $('subtitle').textContent='Defina suas metas mensais e acompanhe o realizado.';
  $('status').innerHTML='';$('content').innerHTML=planningView();bindPlanning();return;
 }

 const year=Number($('year').value),rs=db.entries.filter(r=>selected(r,year)),old=db.entries.filter(r=>selected(r,year-1));
 const issues=db.entries.filter(r=>r.regime===$('regime').value&&r.report_year===year&&r.issue&&(!$('department').value||r.department===$('department').value)&&(!$('package').value||r.package===$('package').value)&&matchesAccount(r));
 $('issueBadge').textContent=issues.length||'';
 const available=db.imports.some(i=>i.active&&i.regime===$('regime').value&&i.report_year===year);
 const priorAvailable=db.imports.some(i=>i.active&&i.regime===$('regime').value&&i.report_year===year-1);
 const titles={dashboard:'Visão geral',entries:'Lançamentos',issues:'Pendências de revisão',imports:'Histórico de importações'};
 $('title').textContent=titles[view];$('subtitle').textContent=view==='dashboard'?'Entenda suas despesas. Acompanhe cada movimento.':view==='issues'?'Dados originais preservados para conferência no sistema de origem.':view==='imports'?'Uma base anual ativa para cada regime. Atualizações ficam registradas.':'Do total ao documento: consulte a composição das despesas.';
 $('status').innerHTML=!available?'<div class="notice">Não existe base importada para este ano e regime. Importe um relatório para começar.</div>':issues.length?`<div class="notice">${integer(issues.length)} movimentos com pendências de data neste ano e regime · Realizado líquido: ${brl(sum(issues))}. Estão fora dos indicadores e gráficos. Consulte Pendências para conferir; o filtro de mês não se aplica a essa contagem.</div>`:'';
 let html='';
 if(view==='dashboard'){
 const total=sum(rs),previous=sum(old),delta=previous?(total-previous)/Math.abs(previous)*100:null;
 html=`<div class="cards"><article class="card featured"><div class="label">Realizado · ${esc($('regime').value)}</div><strong>${available?brl(total):'—'}</strong><small>${$('month').value?months[Number($('month').value)-1]:'Ano completo'} de ${year||'—'} · antes de expurgos</small></article><article class="card"><div class="label">Mesmo período · ${year-1||'—'}</div><strong>${priorAvailable?brl(previous):'—'}</strong><small>Mesmos filtros e regime selecionados</small></article><article class="card"><div class="label">Variação sobre o ano anterior</div><strong class="${delta>0?'bad':'good'}">${available&&priorAvailable&&delta!==null?`${delta>0?'+':''}${delta.toFixed(1).replace('.',',')}%`:'—'}</strong><small>${available&&priorAvailable?brl(total-previous)+' de diferença':'Comparação indisponível'}</small></article>${$('regime').value==='Caixa'?`<article class="card"><div class="label">Diferença em reais entre os anos</div><strong class="${total>previous?'bad':'good'}">${available&&priorAvailable?brl(total-previous):'—'}</strong><small>${available&&priorAvailable?`${year} menos ${year-1} · mesmos filtros e período`:'Comparação indisponível'}</small></article>`:`<article class="card"><div class="label">Comprometido líquido · relatório</div><strong>${available?brl(sum(rs,'committed')):'—'}</strong><small>Separado do Realizado; não somado às despesas</small></article>`}</div>`;
 const monthly=Array.from({length:12},(_,i)=>sum(rs.filter(r=>Number(r.date.slice(5,7))===i+1)));
 const past=Array.from({length:12},(_,i)=>sum(old.filter(r=>Number(r.date.slice(5,7))===i+1)));
 const max=Math.max(1,...monthly.map(Math.abs),...past.map(Math.abs));
 html+=`<div class="grid"><section class="panel"><h2>Evolução das despesas</h2><p class="intro">Realizado por mês · ${monthly.some(x=>x<0)||past.some(x=>x<0)?'Barras mostram magnitude; sinal no valor ao passar o cursor':'Valores nominais, antes dos expurgos'}</p><div class="chart">${months.map((m,i)=>`<div class="col"><div class="bar" title="${m}/${year-1}: ${priorAvailable?brl(past[i]):'sem base'}" style="height:${Math.abs(past[i])/max*95}%"></div><div class="bar now" title="${m}/${year}: ${brl(monthly[i])}" style="height:${Math.abs(monthly[i])/max*95}%"></div><small>${m}</small></div>`).join('')}</div><div class="legend"><span><i style="background:#198573"></i>${year||'Ano atual'}</span><span><i style="background:#d5e4df"></i>${year-1||'Ano anterior'}${priorAvailable?'':' · sem base'}</span></div></section><section class="panel"><h2>Despesas por departamento</h2><p class="intro">Clique em um departamento para filtrar</p>${grouped(rs,'department').map(([name,value],i,all)=>`<button class="rank" data-department="${esc(name)}"><div class="rankhead"><span>${esc(name)}</span><b>${brl(value)}</b></div><div class="track"><span style="width:${Math.min(100,Math.abs(value)/Math.max(1,...all.map(x=>Math.abs(x[1])))*100)}%"></span></div></button>`).join('')||'<div class="empty">Sem dados</div>'}</section></div>`;
 html+=`<section class="panel tablepanel"><div class="tablehead"><div><h2>Composição por pacote</h2><p class="intro">${integer(rs.length)} movimentos no período · clique para explorar</p></div><span class="pill">${esc($('regime').value)}</span></div>${table(['Pacote','Movimentos','Participação','Realizado'],grouped(rs,'package').map(([name,value])=>`<tr><td><button class="reset" data-package="${esc(name)}">${esc(name)}</button></td><td>${integer(rs.filter(r=>r.package===name).length)}</td><td>${total?((value/total)*100).toFixed(1).replace('.',',')+'%':'—'}</td><td class="num">${brl(value)}</td></tr>`))}</section><p class="detail">Comparações refletem a cobertura dos arquivos importados. Os relatórios podem conter datas futuras. Metas disponíveis em Planejamento de metas.</p>`;
 html+=variationSignals(rs,old,year,available,priorAvailable);
 html+=accountsTable(rs,old,year,available,priorAvailable);
 }else if(view==='imports'){
 html=`<section class="panel"><h2>Bases recebidas</h2><p class="intro">Exibe todo o histórico, independentemente dos filtros acima. Uma atualização substitui integralmente o ano e regime selecionados.</p>${table(['Arquivo','Regime','Ano','Importado em','Situação'],db.imports.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.regime)}</td><td>${i.report_year}</td><td>${esc(dateBR(i.imported_at))}</td><td class="num"><span class="pill ${i.active?'':'warn'}">${i.active?'Ativa':'Substituída'}</span></td></tr>`))}</section>`;
 html+=`<section class="panel tablepanel"><h2>Conferência da importação</h2><p class="intro">Sem filtros · total do CSV = realizado elegível no painel + realizado com pendência de data. Comprometido não entra nessa soma.</p>${table(['Arquivo / controle','Linhas CSV / base','Realizado CSV','Realizado base','Diferença','Elegível no painel','Em pendências'],db.imports.filter(i=>i.active).map(i=>`<tr><td>${esc(i.name)}<div class="detail">${esc(i.method||'Controle de origem não disponível')}</div></td><td>${i.source_rows==null?'—':integer(i.source_rows)} / ${integer(i.stored_rows)}</td><td class="num">${i.source_actual==null?'—':brl(i.source_actual)}</td><td class="num">${brl(i.stored_actual)}</td><td class="num">${i.source_actual==null?'—':brl(i.stored_actual-i.source_actual)}</td><td class="num">${brl(i.eligible_actual)}</td><td class="num">${brl(i.pending_actual)}</td></tr>`))}<p class="detail">Para conferir: abra o CSV original no Excel, some apenas a coluna Realizado e compare com Realizado CSV. No painel, mantenha ano completo, todos os departamentos, todos os pacotes e conta vazia. Cada lançamento identifica a importação e a linha original. Não há expurgos aplicados.</p></section>`;
 }else{
 const cash=$('regime').value==='Caixa';
 const source=view==='issues'?issues:(cash?rs.filter(r=>r.actual!==0):rs);
 const filtered=source.filter(r=>[r.document,r.supplier,r.history,r.account,r.vbz,r.department].some(v=>v.toLowerCase().includes(search.toLowerCase())));
 const count=Math.ceil(filtered.length/size);page=Math.max(0,Math.min(page,count-1));
 html=`${view==='issues'?'<div class="notice">Confira estes movimentos no sistema de origem e importe novamente o relatório corrigido. Esta versão não altera datas. Todas as datas possivelmente incorretas da base anual são exibidas aqui, independentemente do mês selecionado.</div>':''}<section class="panel"><div class="tablehead"><div><h2>${view==='issues'?'Movimentos com data possivelmente incorreta':'Consulta de movimentos'}</h2><p class="intro">${integer(filtered.length)} resultados · Realizado líquido ${brl(sum(filtered))}${cash&&view!=='issues'?' · Movimentos com Realizado diferente de zero; inclui estornos.':''}</p></div><input id="search" aria-label="Buscar lançamentos" placeholder="Buscar documento, fornecedor ou conta" value="${esc(search)}"></div>${table(['Data / departamento','Documento / fornecedor','Conta / histórico',...(view==='issues'?['Pendência']:cash?[]:['Comprometido']),'Realizado'],filtered.slice(page*size,(page+1)*size).map(r=>`<tr><td>${esc(dateBR(r.date))}<div class="detail">${esc(r.department)}</div></td><td>${esc(r.document)}<div class="detail">${esc(r.supplier||'Fornecedor não informado')}</div></td><td>${esc(r.account)} · ${esc(r.vbz)}<div class="detail">${esc(r.history)}</div><div class="detail">Origem: importação #${r.import_id}, linha ${r.line}</div></td>${view==='issues'?`<td><span class="pill warn">${esc(r.issue)}</span></td>`:cash?'':`<td>${brl(r.committed)}</td>`}<td class="num">${brl(r.actual)}</td></tr>`))}<div class="pagination"><span>Página ${page+1} de ${Math.max(1,count)}</span><div><button id="prev" ${page===0?'disabled':''}>Anterior</button><button id="next" ${page+1>=count?'disabled':''}>Próxima</button></div></div></section>`;
 }
 $('content').innerHTML=html;
 if($('signalMinimum'))$('signalMinimum').onchange=e=>{const value=Number(e.target.value);if(Number.isFinite(value)&&value>=0){signalMinimum=Math.round(value*100);render();}};
 document.querySelectorAll('[data-department]').forEach(b=>b.onclick=()=>{$('department').value=b.dataset.department;accountOptions();page=0;render();});
 document.querySelectorAll('[data-package]').forEach(b=>b.onclick=()=>{$('package').value=b.dataset.package;accountOptions();page=0;render();});
 document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>{$('account').value=b.dataset.account;page=0;render();window.scrollTo({top:0,behavior:'smooth'});});
 document.querySelectorAll('[data-account-entries]').forEach(b=>b.onclick=()=>{$('account').value=b.dataset.accountEntries;view='entries';search='';page=0;nav();render();window.scrollTo({top:0,behavior:'smooth'});});
 if($('search'))$('search').oninput=e=>{const position=e.target.selectionStart;search=e.target.value;page=0;scheduleSearchRender('search');};
 if($('prev'))$('prev').onclick=()=>{page--;render();};if($('next'))$('next').onclick=()=>{page++;render();};
}
function nav(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;page=0;search='';nav();render();});
months.forEach((name,i)=>$('month').add(new Option(name,String(i+1).padStart(2,'0'))));
['regime','year','month','department','package'].forEach(id=>$(id).onchange=()=>{page=0;accountOptions();render();});
$('account').oninput=()=>{page=0;scheduleSearchRender('account');};
$('reset').onclick=()=>{['month','department','package','account'].forEach(id=>$(id).value='');search='';page=0;accountOptions();render();};
load().catch(error=>{$('status').innerHTML=`<div class="error">${esc(error.message)} Atualize a página para tentar novamente.</div>`;});
